-- +goose Up
INSERT INTO workflow_states(project_id,source_name,detent_state,terminal,dispatchable,created_at,updated_at)
SELECT p.id, destinations.name, destinations.name, destinations.terminal, 0, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now')
FROM projects p CROSS JOIN (SELECT 'Backlog' AS name, 0 AS terminal UNION ALL SELECT 'Cancelled', 1) destinations
WHERE p.profile='native' AND p.workflow_source='' AND p.workflow_markdown=''
AND json(p.states_json)=json('[{"name":"Triage","terminal":false,"dispatchable":false,"transitions":["Todo"]},{"name":"Todo","terminal":false,"dispatchable":true,"transitions":["In Progress","Done"]},{"name":"In Progress","terminal":false,"dispatchable":true,"transitions":["Todo","Blocked","Human Review","Merging","Done"]},{"name":"Blocked","terminal":false,"dispatchable":false,"transitions":["Todo","In Progress","Done"]},{"name":"Human Review","terminal":false,"dispatchable":false,"transitions":["Done","In Progress","Blocked","Merging"]},{"name":"Merging","terminal":false,"dispatchable":true,"transitions":["Done","Blocked","Human Review","In Progress"]},{"name":"Done","terminal":true,"dispatchable":false,"transitions":["Todo"]}]')
AND NOT EXISTS (SELECT 1 FROM workflow_states w WHERE w.project_id=p.id AND w.source_name=destinations.name);

UPDATE projects AS p SET states_json='[{"name":"Triage","terminal":false,"dispatchable":false,"transitions":["Todo","Backlog","Cancelled"]},{"name":"Todo","terminal":false,"dispatchable":true,"transitions":["In Progress","Done","Cancelled"]},{"name":"In Progress","terminal":false,"dispatchable":true,"transitions":["Todo","Blocked","Human Review","Merging","Done","Cancelled"]},{"name":"Blocked","terminal":false,"dispatchable":false,"transitions":["Todo","In Progress","Done","Cancelled"]},{"name":"Human Review","terminal":false,"dispatchable":false,"transitions":["Done","In Progress","Blocked","Merging","Cancelled"]},{"name":"Merging","terminal":false,"dispatchable":true,"transitions":["Done","Blocked","Human Review","In Progress","Cancelled"]},{"name":"Done","terminal":true,"dispatchable":false,"transitions":["Todo"]},{"name":"Backlog","terminal":false,"dispatchable":false,"transitions":["Todo","Cancelled"]},{"name":"Cancelled","terminal":true,"dispatchable":false,"transitions":["Todo"]}]'
WHERE p.profile='native' AND p.workflow_source='' AND p.workflow_markdown=''
AND json(p.states_json)=json('[{"name":"Triage","terminal":false,"dispatchable":false,"transitions":["Todo"]},{"name":"Todo","terminal":false,"dispatchable":true,"transitions":["In Progress","Done"]},{"name":"In Progress","terminal":false,"dispatchable":true,"transitions":["Todo","Blocked","Human Review","Merging","Done"]},{"name":"Blocked","terminal":false,"dispatchable":false,"transitions":["Todo","In Progress","Done"]},{"name":"Human Review","terminal":false,"dispatchable":false,"transitions":["Done","In Progress","Blocked","Merging"]},{"name":"Merging","terminal":false,"dispatchable":true,"transitions":["Done","Blocked","Human Review","In Progress"]},{"name":"Done","terminal":true,"dispatchable":false,"transitions":["Todo"]}]');

-- +goose Down
SELECT 1;
